// RainData.h — shared data model for the rain radar feature (MODE_RAIN).
//
// A RainViewer radar frame arrives as a square PNG (256 px RGBA) centred on
// the home position. The PNG is decoded once, on the device, into a 240x240
// 8-bit file: each pixel becomes the index of its display colour in
// kRainColors (57,600 B/frame) in LittleFS under /rain/t<time>.raw.
//
// kRainColors (rain_palette.h, generated by tools/make_rain_palette.py from
// RainViewer's published colour table) holds every colour of the scheme the
// firmware requests, rain and snow levels, premultiplied on black (the
// screen's background): the screen shows what RainViewer renders, with no
// reinterpreted palette.
#pragma once
#include <Arduino.h>
#include "config.h"
#include "rain_palette.h"

// A short string kept in flash (PSTR), copied to the stack only where an API
// takes a RAM string (LittleFS paths, the GFX text calls). On the ESP8266 a
// plain literal sits in RAM for good, rain on or off: the rain mode keeps
// its literals in flash this way. The copy lives until the end of the full
// expression: pass it straight to the call, never keep the pointer.
struct RainStr {
  char s[32];
  explicit RainStr(PGM_P p) { strncpy_P(s, p, sizeof s - 1); s[sizeof s - 1] = 0; }
  operator const char*() const { return s; }
};
#define RAIN_P(lit)     RainStr(PSTR(lit))
#define RAIN_PATH(name) RAIN_P(RAIN_DIR name)   // e.g. RAIN_PATH("/meta.json")

// One radar frame, oldest first. Times are unix UTC timestamps.
struct RainFrame {
  uint32_t time;
  bool     nowcast;   // true = prediction frame (beyond "now")
};


// Premultiplied RGB565 -> index in kRainColors (the 32 KB lookup of
// rain_clut.h, generated by tools/make_rain_palette.py).
uint8_t rainColorIndex(uint16_t rgb565);
